function planScratchBuild(steps) {
  const count = steps.length;
  if (count === 0) return [];

  const indexByKey = new Map();
  const dependents = Array.from({ length: count }, () => []);
  const remaining = new Array(count).fill(0);
  const keys = new Array(count);

  for (let i = 0; i < count; i++) {
    keys[i] = steps[i].key;
    indexByKey.set(steps[i].key, i);
  }

  for (let i = 0; i < count; i++) {
    const needs = new Set(steps[i].needs);
    remaining[i] = needs.size;

    for (const need of needs) {
      dependents[indexByKey.get(need)].push(i);
    }
  }

  const heap = [];

  function push(value) {
    let i = heap.length;
    heap.push(value);

    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (heap[parent] <= value) break;
      heap[i] = heap[parent];
      i = parent;
    }

    heap[i] = value;
  }

  function pop() {
    const first = heap[0];
    const last = heap.pop();

    if (heap.length > 0) {
      let i = 0;

      while (true) {
        const left = i * 2 + 1;
        if (left >= heap.length) break;

        const right = left + 1;
        let child = left;

        if (right < heap.length && heap[right] < heap[left]) {
          child = right;
        }

        if (heap[child] >= last) break;

        heap[i] = heap[child];
        i = child;
      }

      heap[i] = last;
    }

    return first;
  }

  for (let i = 0; i < count; i++) {
    if (remaining[i] === 0) push(i);
  }

  const result = [];

  while (heap.length > 0) {
    const index = pop();
    result.push(keys[index]);

    for (const dependent of dependents[index]) {
      remaining[dependent]--;

      if (remaining[dependent] === 0) {
        push(dependent);
      }
    }
  }

  return result.length === count ? result : null;
}
